27	@OptIn(FlowPreview::class)
28	@HiltViewModel
29	class NotificationFilterViewModel @Inject constructor(
30	    private val notificationFilterUseCases: NotificationFilterUseCases,
31	    private val sharedPref: Preferences,
32	    private val repository: ly.com.tahaben.notification_filter_domain.repository.NotificationRepository,
33	    private val serviceUtil: ServiceUtil
34	) : ViewModel() {
35	
36	
37	    var state by mutableStateOf(NotificationFilterState())
38	        private set
39	
40	    private var getNotificationsJob: Job? = null
41	
42	    init {
43	        checkServiceStats()
44	        isFirstTimeOpened()
45	    }
46	
47	    fun checkServiceStats() {
48	        viewModelScope.launch {
49	            state = state.copy(
50	                isServiceEnabled = notificationFilterUseCases
51	                    .checkIfNotificationServiceIsEnabled()
52	            )
53	        }
54	        checkIfNotificationAccessGranted()
55	    }
56	
57	    private fun checkIfNotificationAccessGranted() {
58	        state = state.copy(
59	            isPermissionGranted = notificationFilterUseCases.checkIfNotificationAccessIsGranted()
60	        )
61	    }
62	
63	    fun startNotificationService() {
64	        notificationFilterUseCases.startNotificationService()
65	        setServiceEnabled()
66	    }
67	
68	    fun startObserving() { getNotifications() }
69	    fun stopObserving() { getNotificationsJob?.cancel() }
70	    fun nextPage() { state = state.copy(page = state.page + 1); getNotifications() }
71	    fun previousPage() { state = state.copy(page = (state.page - 1).coerceAtLeast(0)); getNotifications() }
72	
73	    private fun getNotifications() {
74	        getNotificationsJob?.cancel()
75	        val query = ly.com.tahaben.notification_filter_domain.inbox.InboxQuery(
76	            cleared = state.showCleared, priority = state.priorityFilter,
77	            standingCutoff = System.currentTimeMillis() - sharedPref.getStandingThresholdHours() * 3_600_000L,
78	            offset = state.page * 100, limit = 101)
79	        getNotificationsJob = repository.observeInbox(query).onEach { rows ->
80	            val page = rows.take(100)
81	            state = state.copy(hasNextPage = rows.size > 100)
82	            if (query.cleared) state = state.copy(clearedNotifications = page)
83	            else applyNotificationList(page)
84	        }.launchIn(viewModelScope)
85	    }
86	
87	    private fun applyNotificationList(notifications: List<NotificationItem>) {
88	        val nowMillis = System.currentTimeMillis()
89	        val standingThresholdHours = sharedPref.getStandingThresholdHours()
90	        val filtered = NotificationInboxFilter.filter(
91	            notifications = notifications,
92	            priorityFilter = state.priorityFilter,
93	            standingThresholdHours = standingThresholdHours,
94	            nowMillis = nowMillis,
95	        )
96	        val displayPriorities = filtered.associate { item ->
97	            item.id to NotificationInboxFilter.effectivePriority(
98	                item = item,
99	                standingThresholdHours = standingThresholdHours,
100	                nowMillis = nowMillis,
101	            )
102	        }
103	        val actions = filtered.associate { item ->
104	            item.id to serviceUtil.getNotificationActionTitles(item.id)
105	        }.filterValues { it.isNotEmpty() }
106	        state = state.copy(
107	            isServiceEnabled = true,
108	            allNotifications = notifications,
109	            filteredNotifications = filtered,
110	            notificationActions = actions,
111	            displayPriorities = displayPriorities,
112	        )
113	    }
114	
115	    fun onEvent(event: NotificationFilterEvent) {
116	        when (event) {
117	            is NotificationFilterEvent.OnOpenNotification -> {
118	                Timber.d("notification click viewmodel")
119	                notificationFilterUseCases.openNotification(
120	                    event.notificationItem.id,
121	                    event.notificationItem.packageName
122	                )
123	                viewModelScope.launch {
124	                    withContext(Dispatchers.IO) {
125	                        notificationFilterUseCases.markNotificationRead(event.notificationItem.id)
126	                    }
127	                }
128	                deleteNotificationData(event.notificationItem)
129	            }
130	            is NotificationFilterEvent.OnDismissNotification -> {
131	                deleteNotificationData(event.notificationItem)
132	            }
133	            is NotificationFilterEvent.OnDeleteAllNotifications -> {
134	                Timber.d("delete all notifications")
135	                deleteAllNotifications()
136	            }
137	
138	            is NotificationFilterEvent.OnExcludeAppClick -> {
139	                notificationFilterUseCases.setAppPriorityOverride(
140	                    event.appPackageName,
141	                    NotificationPriority.CRITICAL,
142	                )
143	            }
144	
145	            is NotificationFilterEvent.OnLaunchAppInfoClick -> {
146	                serviceUtil.launchAppInfo(event.appPackageName)
147	            }
148	
149	            is NotificationFilterEvent.OnSetPriorityFilter -> {
150	                state = state.copy(priorityFilter = event.priority)
151	                state = state.copy(page = 0)
152	                getNotifications()
153	            }
154	
155	            NotificationFilterEvent.OnToggleClearedView -> {
156	                state = state.copy(showCleared = !state.showCleared, page = 0)
157	                getNotifications()
158	            }
159	
160	            is NotificationFilterEvent.OnFireNotificationAction -> {
161	                serviceUtil.fireNotificationAction(event.notificationId, event.actionIndex)
162	            }
163	        }
164	    }
165	
166	    private fun deleteNotificationData(notificationItem: NotificationItem) {
167	        viewModelScope.launch {
168	            withContext(Dispatchers.IO) {
169	                notificationFilterUseCases.deleteNotificationFromDB(
170	                    notificationItem
171	                )
172	                notificationFilterUseCases.deleteNotificationIntentFromHashmap(
173	                    notificationItem.id
174	                )
175	            }
176	        }
177	    }
178	
179	    private fun deleteAllNotifications() {
180	        viewModelScope.launch {
181	            withContext(Dispatchers.IO) {
182	                notificationFilterUseCases.deleteAllNotifications()
183	            }
184	        }
185	    }
186	
187	    private fun setServiceEnabled() {
188	        notificationFilterUseCases.setServiceState(true)
189	        state = state.copy(
190	            isServiceEnabled = true
191	        )
192	    }
193	
194	    fun isFirstTimeOpened() {
195	        state = state.copy(
196	            isFirstTimeOpened = sharedPref.loadShouldShowcase()
197	        )
198	        Timber.d("sholdShowcase ${state.isFirstTimeOpened}")
199	    }
200	
201	    fun setShowcased() {
202	        sharedPref.saveShouldShowcase(false)
203	        state = state.copy(
204	            isFirstTimeOpened = false
205	        )
206	    }
207	
208	    fun openAppSettings() {
209	        notificationFilterUseCases.openAppSettings()
210	    }
211	
212	    companion object {
213	        private const val NOTIFICATION_LIST_DEBOUNCE_MS = 150L
214	    }
215	}

