/**
 * Process-wide cache of rasterised launcher icons. A list row reads it synchronously while composing, so
 * an icon that was already shown does not flash in again as the row scrolls back into view.
 */
internal object AppIconCache {
    private const val MAX_BYTES = 6 * 1024 * 1024

    private val bitmaps = object : LruCache<String, ImageBitmap>(MAX_BYTES) {
        override fun sizeOf(key: String, value: ImageBitmap): Int = value.width * value.height * 4
    }
    private val missing = ConcurrentHashMap.newKeySet<String>()

    private fun key(packageName: String, sizePx: Int) = "$packageName@$sizePx"

    fun peek(packageName: String, sizePx: Int): ImageBitmap? = bitmaps.get(key(packageName, sizePx))

    fun isMissing(packageName: String): Boolean = packageName in missing

    /** Blocking: call from a background dispatcher. Returns null when the package has no icon to show. */
    fun load(packageManager: PackageManager, packageName: String, sizePx: Int): ImageBitmap? {
        peek(packageName, sizePx)?.let { return it }
        if (packageName in missing) return null
        val drawable = try {
            packageManager.getApplicationIcon(packageName)
        } catch (_: PackageManager.NameNotFoundException) {
            missing += packageName
            return null
        } catch (_: RuntimeException) {
            return null
        }
        val bitmap = Bitmap.createBitmap(sizePx, sizePx, Bitmap.Config.ARGB_8888)
        drawable.setBounds(0, 0, sizePx, sizePx)
        drawable.draw(Canvas(bitmap))
        return bitmap.asImageBitmap().also { bitmaps.put(key(packageName, sizePx), it) }
    }
}

/**
 * The launcher icon of [packageName] in a fixed [size] square. The square is reserved from the first frame, so
 * rows keep their height while the icon loads; an app with no icon shows its initial instead.
 */
@Composable
fun AppIcon(
    packageName: String,
    appName: String?,
    modifier: Modifier = Modifier,
    size: Dp = 40.dp,
) {
    val context = LocalContext.current
    val sizePx = with(LocalDensity.current) { size.roundToPx() }
    var icon by remember(packageName, sizePx) { mutableStateOf(AppIconCache.peek(packageName, sizePx)) }
    if (icon == null && !AppIconCache.isMissing(packageName)) {
        LaunchedEffect(packageName, sizePx) {
            icon = withContext(Dispatchers.IO) { AppIconCache.load(context.packageManager, packageName, sizePx) }
        }
    }
    val shape = RoundedCornerShape(size / 4)
    val loaded = icon
    if (loaded != null) {
        Image(
            bitmap = loaded,
            contentDescription = null,
            modifier = modifier.size(size).clip(shape),
        )
    } else {
        Box(
            modifier = modifier
                .size(size)
                .clip(shape)
                .background(MaterialTheme.colorScheme.secondaryContainer),
            contentAlignment = Alignment.Center,
        ) {
            Text(
                text = (appName ?: packageName).firstOrNull { it.isLetterOrDigit() }?.uppercase().orEmpty(),
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSecondaryContainer,
            )
        }
    }
}
