    val onAction: (notificationId: String, actionIndex: Int) -> Unit,
    val onAlwaysAllow: (NotificationItem) -> Unit,
    val onAppInfo: (packageName: String) -> Unit,
    val onToggleThread: (threadKey: String) -> Unit,
)

private val CardShape = RoundedCornerShape(8.dp)
private val PillShape = RoundedCornerShape(4.dp)
private const val MAX_EXPANDED_MESSAGES = 30

fun priorityColor(priority: NotificationPriority): Color = when (priority) {
    NotificationPriority.CRITICAL -> Color(0xFFF44336)
    NotificationPriority.HIGH -> Color(0xFFFF9800)
    NotificationPriority.MEDIUM -> Color(0xFF2196F3)
