            background = deliveryTint.copy(alpha = 0.15f),
            icon = deliveryIcon(message.delivery),
        )
        Pill(
            text = message.displayPriority.name.lowercase().replaceFirstChar { it.uppercase() },
            color = priorityTint,
            background = priorityTint.copy(alpha = 0.15f),
