/**
 * The shared card chrome: priority rail, app icon, content column, press ripple and long-press menu.
 * Sent cards are filled; unsent ones are outlined, so the two read differently before any label is read.
 * The menu is only composed while open, and its anchor comes from the press position rather than a
 * per-row size measurement.
 */
@Composable
private fun CardFrame(
    delivery: DeliveryState,
    isRead: Boolean,
    priority: NotificationPriority,
    packageName: String,
    appName: String?,
    onClick: () -> Unit,
    menuItems: List<Pair<String, () -> Unit>>,
    modifier: Modifier = Modifier,
    animateSize: Boolean = false,
    content: @Composable () -> Unit,
) {
    val isRtl = LocalLayoutDirection.current == androidx.compose.ui.unit.LayoutDirection.Rtl
    val interactionSource = remember { MutableInteractionSource() }
    var menuAnchor by remember { mutableStateOf<IntOffset?>(null) }
    val currentOnClick by rememberUpdatedState(onClick)
    val containerColor = if (isRead) MaterialTheme.colorScheme.surfaceVariant
    else MaterialTheme.colorScheme.primaryContainer
    val unsent = delivery != DeliveryState.SENT

    Box(
        modifier = modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp)
            .then(if (animateSize) Modifier.animateContentSize() else Modifier)
            .clip(CardShape)
            .background(containerColor)
            .then(
                if (unsent) Modifier.border(1.dp, deliveryColor(delivery).copy(alpha = 0.6f), CardShape)
                else Modifier
            )
            .indication(interactionSource, LocalIndication.current)
            .pointerInput(Unit) {
                detectTapGestures(
                    onLongPress = { menuAnchor = IntOffset(it.x.roundToInt(), it.y.roundToInt()) },
                    onPress = {
                        val press = PressInteraction.Press(it)
                        interactionSource.emit(press)
                        tryAwaitRelease()
                        interactionSource.emit(PressInteraction.Release(press))
                    },
                    onTap = { currentOnClick() },
                )
            },
    ) {
        Row(modifier = Modifier.fillMaxWidth()) {
            Box(
                modifier = Modifier
                    .width(4.dp)
                    .fillMaxHeight()
                    .background(priorityColor(priority))
            )
            Row(
                modifier = Modifier
                    .weight(1f)
                    .padding(start = 8.dp, end = 12.dp, top = 8.dp, bottom = 8.dp),
                horizontalArrangement = Arrangement.spacedBy(12.dp),
            ) {
                AppIcon(packageName = packageName, appName = appName, size = 40.dp)
                Column(
                    modifier = Modifier.weight(1f),
                    verticalArrangement = Arrangement.spacedBy(2.dp),
                ) { content() }
            }
        }
        menuAnchor?.let { anchor ->
            // A zero-size box at the press point: the menu opens where the finger was.
            Box(modifier = Modifier.absoluteOffset { anchor }) {
                DropdownMenu(expanded = true, onDismissRequest = { menuAnchor = null }) {
                    menuItems.forEach { (text, action) ->
                        DropdownMenuItem(text = { Text(text = text) }, onClick = {
                            menuAnchor = null
                            action()
                        })
                    }
                }
            }
        }
    }
}

