import ly.com.tahaben.core.R

/**
 * Swipe toward the end edge to clear a card. The red delete background is composed only while a swipe is
 * in progress; at rest the box is just its content, which keeps a long list of them cheap to scroll.
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SwipeToClearBox(
    onClear: () -> Unit,
    modifier: Modifier = Modifier,
    content: @Composable () -> Unit,
) {
    val currentOnClear by rememberUpdatedState(onClear)
    val contentDirection = LocalLayoutDirection.current
    val dismissState = rememberSwipeToDismissBoxState(
        initialValue = SwipeToDismissBoxValue.Settled,
        confirmValueChange = {
            if (it == SwipeToDismissBoxValue.EndToStart) {
                currentOnClear()
                true
            } else {
                false
            }
        },
    )
    // SwipeToDismissBox mis-handles RTL, so it runs in LTR and its content is put back in the real direction.
    CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Ltr) {
        SwipeToDismissBox(
            modifier = modifier,
            state = dismissState,
            enableDismissFromStartToEnd = false,
            backgroundContent = {
                if (dismissState.dismissDirection != SwipeToDismissBoxValue.Settled) {
                    Box(
                        modifier = Modifier
                            .fillMaxSize()
                            .background(MaterialTheme.colorScheme.error)
                            .padding(horizontal = 20.dp),
                        contentAlignment = Alignment.CenterEnd,
                    ) {
                        Icon(
                            imageVector = Icons.Default.Delete,
                            contentDescription = stringResource(R.string.delete_icon),
                            tint = MaterialTheme.colorScheme.onError,
                        )
                    }
                }
            },
            content = {
                CompositionLocalProvider(LocalLayoutDirection provides contentDirection) { content() }
            },
        )
    }
}
