package ly.com.tahaben.notification_filter_domain.inbox

/**
 * Finds a one-time verification code in notification text.
 *
 * A code counts only when it sits next to a verification word ("code", "OTP", "PIN", "passcode",
 * "verification", "security", "authentication") in the same sentence, so order numbers, amounts,
 * times and phone numbers are left alone. Codes are 4-8 digits, optionally written with one space
 * or hyphen in the middle ("123 456"), or a Google-style "G-123456".
 */
object OtpCodeExtractor {
    private const val CODE = """(?:[A-Z]-)?\d{3,4}[ -]?\d{1,4}|\d{4,8}"""
    private const val WORD = """(?:one[- ]time|verification|security|authentication|login|sign[- ]?in|confirmation|access|auth)?\s*(?:code|otp|pin|passcode|password)"""

    private val wordThenCode = Regex("""(?i)\b$WORD\b[^.\n\d]{0,40}?(?<![\d.,:$])($CODE)(?![\d.,:%]|\s?(?:am|pm)\b)""")
    private val codeThenWord = Regex("""(?i)(?<![\d.,:$])($CODE)(?![\d.,:%])[^.\n\d]{0,25}?\b(?:is|as)\s+(?:your|the)\b[^.\n]{0,30}?\b$WORD\b""")

    fun extract(title: String?, text: String?): String? {
        val haystack = listOfNotNull(title, text).joinToString("\n")
        if (haystack.isBlank()) return null
        val match = wordThenCode.find(haystack) ?: codeThenWord.find(haystack) ?: return null
        val code = match.groupValues[1].trim()
        val digits = code.count(Char::isDigit)
        return code.takeIf { digits in 4..8 }
    }
}
