    fun generate(nowMillis: Long): AdbIdentity {
        val random = SecureRandom()
        val keyPair = KeyPairGenerator.getInstance("RSA").apply { initialize(2048, random) }.generateKeyPair()
        val subject = X500Name("CN=farhan")
