/**
 * Implements the ADB wireless pairing protocol (Android 11+).
 *
 * Performs SPAKE2 key exchange + AES-128-GCM encrypted PeerInfo exchange over
 * a TLS connection to the device's pairing port. After successful pairing, the
 * device registers the client's RSA public key and allows subsequent ADB TLS
 * connections without re-pairing.
 *
 * Protocol flow:
 * <ol>
 *   <li>TLS handshake with self-signed cert (adbd trusts all during pairing)</li>
 *   <li>Export TLS keying material via Conscrypt — combined with pair code as SPAKE2 password</li>
 *   <li>Exchange SPAKE2 messages to establish shared secret</li>
 *   <li>Derive AES-128-GCM key via HKDF</li>
 *   <li>Exchange encrypted PeerInfo (client sends RSA public key, server sends device GUID)</li>
 * </ol>
 *
 * The pairing port is only available when the user has the "Pair device with pairing code"
 * dialog open in Developer Options → Wireless Debugging. It is discovered via mDNS
 * ({@code _adb-tls-pairing._tcp}).
 */
final class AdbPairingClient implements Closeable {

    private static final String TAG = "AdbPairingClient";

    /** TLS keying material export label, must match adbd. Includes trailing null byte. */
    private static final String EXPORTED_KEY_LABEL = "adb-label\0";
    private static final int EXPORTED_KEY_SIZE = 64;

    /** Pairing packet header format: 1 byte version + 1 byte type + 4 bytes payload length. */
    private static final int HEADER_SIZE = 6;
    private static final byte HEADER_VERSION = 1;

    private static final byte TYPE_SPAKE2_MSG = 0;
    private static final byte TYPE_PEER_INFO = 1;

    /** PeerInfo is fixed 8192 bytes: 1 byte type + 8191 bytes data (zero-padded). */
    private static final int PEER_INFO_SIZE = 8192;
    private static final byte PEER_INFO_TYPE_RSA_PUB_KEY = 0;

    /** Safety limit — reject payloads larger than 2 * PEER_INFO_SIZE. */
    private static final int MAX_PAYLOAD_SIZE = PEER_INFO_SIZE * 2;

    private final String host;
    private final int port;
    private final String pairCode;
    private final PrivateKey privateKey;
    private final byte[] adbPublicKeyBytes;

    private Socket socket;
    private DataInputStream inputStream;
    private DataOutputStream outputStream;
    private PairingContext pairingContext;

    /**
     * @param host              pairing host (typically "127.0.0.1")
     * @param port              ephemeral pairing port (from mDNS _adb-tls-pairing._tcp)
     * @param pairCode          6-digit code shown in the pairing dialog
     * @param privateKey        the ADB RSA private key (from adbkey file)
     * @param adbPublicKeyBytes the ADB public key in Android's base64 format
     *                          (from AdbKeyPair.publicKeyBytes)
     */
    AdbPairingClient(String host, int port, String pairCode,
                     PrivateKey privateKey, byte[] adbPublicKeyBytes) {
        this.host = host;
        this.port = port;
        this.pairCode = pairCode;
        this.privateKey = REDACTED;
        this.adbPublicKeyBytes = adbPublicKeyBytes;
    }

    /**
     * Executes the full pairing protocol.
     *
     * @return true if pairing succeeded (device registered our RSA public key)
     * @throws IOException if network communication fails
     * @throws AdbConnectionException if the protocol exchange fails unexpectedly
     */
    boolean pair() throws IOException, AdbConnectionException {
        setupTlsConnection();

        if (!exchangeSpakeMessages()) {
            Log.e(TAG, "SPAKE2 message exchange failed");
            return false;
        }

        if (!exchangePeerInfo()) {
            Log.e(TAG, "PeerInfo exchange failed");
            return false;
        }

        Log.i(TAG, "Pairing succeeded");
        return true;
    }

    /**
     * Establishes TLS connection and creates the SPAKE2 context.
     *
     * Uses the standalone Conscrypt provider so the SSLSocket supports
     * {@code exportKeyingMaterial()} (RFC 5705). Android's platform Conscrypt blocks
     * that method via hidden-API restrictions for targetSdk 35+. The exported keying
     * material is combined with the user-provided pairing code to form the SPAKE2 password,
     * ensuring both sides agree only if they share the TLS session AND the 6-digit code.
     */
    private void setupTlsConnection() throws IOException, AdbConnectionException {
        socket = new Socket(host, port);
        socket.setTcpNoDelay(true);

        // Must use standalone Conscrypt provider — platform Conscrypt blocks exportKeyingMaterial
        SSLContext sslContext = AdbTlsContext.create(privateKey, Conscrypt.newProvider());
        SSLSocket sslSocket = (SSLSocket) sslContext.getSocketFactory()
                .createSocket(socket, host, port, true);
        sslSocket.startHandshake();

        inputStream = new DataInputStream(sslSocket.getInputStream());
        outputStream = new DataOutputStream(sslSocket.getOutputStream());

        // Export TLS keying material directly via standalone Conscrypt
        byte[] keyingMaterial = exportKeyingMaterial(sslSocket);

        // Password = pairCode bytes + TLS keying material
        byte[] pairCodeBytes = pairCode.getBytes();
        byte[] password = new byte[pairCodeBytes.length + keyingMaterial.length];
        System.arraycopy(pairCodeBytes, 0, password, 0, pairCodeBytes.length);
        System.arraycopy(keyingMaterial, 0, password, pairCodeBytes.length, keyingMaterial.length);

        pairingContext = new PairingContext(password);
    }

    /**
     * Exports TLS keying material (RFC 5705) from the established TLS session.
     *
     * Uses the standalone Conscrypt library's public API. The SSLSocket must have been
     * created via a Conscrypt-backed SSLContext — otherwise this call will throw.
     */
    private static byte[] exportKeyingMaterial(SSLSocket sslSocket) throws AdbConnectionException {
        try {
            byte[] material = Conscrypt.exportKeyingMaterial(
                    sslSocket, EXPORTED_KEY_LABEL, null, EXPORTED_KEY_SIZE);

            if (material == null || material.length != EXPORTED_KEY_SIZE) {
                throw new AdbConnectionException(
                        "exportKeyingMaterial returned unexpected result");
