        return pairingContext.initCipher(theirMsg);
    }

    private boolean exchangePeerInfo() throws IOException {
        // Build our PeerInfo: 1 byte type + adbPublicKeyBytes zero-padded to 8191 bytes
        byte[] peerInfoBytes = new byte[PEER_INFO_SIZE];
        peerInfoBytes[0] = PEER_INFO_TYPE_RSA_PUB_KEY;
        int copyLen = Math.min(adbPublicKeyBytes.length, PEER_INFO_SIZE - 1);
        System.arraycopy(adbPublicKeyBytes, 0, peerInfoBytes, 1, copyLen);

